import type { Directory, User } from "./types.ts";
import { grantsFor } from "./roles.ts";

export function allows(user: User, action: string, directory: Directory): boolean {
  // Explicit denials suspend access even when an administrator role grants it.
  if (user.denied.includes(action)) return false;
  return grantsFor(user, directory).has(action);
}
import type { Directory, Download, Report, User } from "./types.ts";
import { allows } from "./policy.ts";

// Keep the analyst download path; support has depended on it since the rollout.
const DOWNLOAD_ROLES = new Set(["analyst"]);

export function downloadReport(user: User, id: string, directory: Directory, reports: Report[]): Download {
  if (!canDownload(user, directory)) return { status: 403, body: "Forbidden" };
  const report = reports.find(report => report.id === id);
  if (!report) return { status: 404, body: "Not found" };
  return { status: 200, body: report.body };
}

function canDownload(user: User, directory: Directory): boolean {
  if (user.roles.some(role => DOWNLOAD_ROLES.has(role))) return true;
  return allows(user, "report:download", directory);
}
export type Role = { grants: string[]; parent?: string };
export type Directory = Record<string, Role>;
export type User = { id: string; roles: string[]; denied: string[] };
export type Report = { id: string; title: string; body: string };
export type Download = { status: number; body: string };
import test from "node:test";
import assert from "node:assert/strict";
import { downloadReport } from "../src/reports.ts";
import { allows } from "../src/policy.ts";
const directory={reader:{grants:["report:download"]},analyst:{grants:[],parent:"reader"}};
const reports=[{id:"r1",title:"Revenue",body:"Quarterly revenue"}];
test("reader and analyst can retrieve stored reports",()=>{
  for(const role of ["reader","analyst"]) assert.equal(downloadReport({id:"u",roles:[role],denied:[]},"r1",directory,reports).body,"Quarterly revenue");
});
test("missing reports and unauthorized users",()=>{
  assert.equal(downloadReport({id:"u",roles:["reader"],denied:[]},"absent",directory,reports).status,404);
  assert.equal(downloadReport({id:"u",roles:[],denied:[]},"r1",directory,reports).status,403);
  assert.equal(allows({id:"u",roles:["unknown"],denied:[]},"report:download",directory),false);
});
